mapper.update:
update red_packet_item
set status    = 0,
    user_id   = null,
    grab_time = null
where packet_no = #{packetNo}
  and seq = #{seq}
  and status = 1
  and user_id = #{userId}

mapper.select:
select count(1)
from red_packet_item
where packet_no = #{packetNo}
  and user_id = #{userId}
